text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لخدمات شركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "لإتمام التسجيل في خدمة النشرة البريدية الإخبارية، يشترط على المستخدم تقديم صورة طبق الأصل من بطاقة الهوية الوطنية، وتحديد الحالة الاجتماعية، وعدد أفراد الأسرة، واسم جهة العمل الحالية."
    },
    {
      "slot": "p2",
      "text": "تحتفظ الشركة بسجلات كافة بيانات المستخدمين ضمن أرشيفها الرقمي لأغراض تطوير الأداء والجودة بشكل دائم، ودون الالتزام بإجراء عمليات إتلاف دورية لها حتى بعد انتهاء العلاقة التعاقدية."
    },
    {
      "slot": "p3",
      "text": "لا تفصح هذه الوثيقة عن تفاصيل أنواع البيانات التي يتم جمعها أو الأغراض المحددة لمعالجتها، ويمكن للمستخدمين الاستفسار عن طبيعة البيانات المخزنة بعد إتمام عملية التسجيل حصراً."
    },
    {
      "slot": "p4",
      "text": "نطلب تقديم التقارير الطبية وشهادات اللياقة البدنية فقط للراغبين في شغل الوظائف التشغيلية الميدانية التي تتطلب طبيعتها التأكد من السلامة الجسدية وفقاً لمتطلبات بيئة العمل."
    },
    {
      "slot": "p5",
      "text": "تتم معالجة بيانات الاستخدام بناءً على موافقة المستخدم الصريحة التي تمنحنا الحق في الاستخدام، مع الاحتفاظ بحق العميل في سحب هذه الموافقة في أي وقت دون إبداء أسباب."
    }
  ],
  "neutral": [
    "تخضع جميع المدفوعات المالية لرسوم إدارية إضافية تُحتسب بناءً على قيمة المعاملة وطريقة الدفع المكتسبة عبر بوابة الدفع الإلكترونية.",
    "تبدأ هذه الاتفاقية فور إتمام المستخدم عملية التسجيل وتنتهي بناءً على طلب أحد الطرفين وفقاً لآليات الإنهاء الموضحة هنا.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر المالية الناشئة عن استخدام المنصة أو تعطلها المؤقت.",
    "تخضع هذه الشروط وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية وتختص الجهات القضائية بالفصل في أي نزاع.",
    "تعتبر كافة حقوق الملكية الفكرية والعلامات التجارية المرتبطة بالتصميم والمحتوى ملكاً حصرياً للشركة ولا يُسمح بنسخها أو استغلالها دون إذن خطي مسبق."
  ]
}
